// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(address actor, uint8 roleSel) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        bytes32 role;
        if (roleSel % 3 == 0) role = c.PROPOSER_ROLE();
        else if (roleSel % 3 == 1) role = c.EXECUTOR_ROLE();
        else role = c.TIMELOCK_ADMIN_ROLE();

        // admin (this contract) grants the role to actor first
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor));

        // actor renounces the role for itself
        vm.prank(actor);
        c.renounceRole(role, actor);

        // general rule: renouncing always removes the role from the renouncer
        assertTrue(!c.hasRole(role, actor));
    }
}
